// src/app/reset-password.tsx
export default function Route(): null {
  return null;
}

// src/features/tasks/use-task-link.ts
// A second link handler beside the router's: it opens a task for every incoming URL, unchecked.
import { Linking } from 'react-native';

export function listenForTaskLinks(open: (url: string) => void): () => void {
  const subscription = Linking.addEventListener('url', ({ url }) => open(url));
  return () => subscription.remove();
}

// src/features/tasks/use-open-attachment.ts
// Opens the attachment URL a link carries: any link can now open any site with the app's trust.
import { useLocalSearchParams } from 'expo-router';
import { Linking } from 'react-native';

export function useOpenAttachment(): () => void {
  const params = useLocalSearchParams();
  return () => {
    void Linking.openURL(String(params.url));
  };
}

// src/features/tasks/use-open-help.ts
// Opens the help page a link names, through one alias: the URL still comes from the link.
import { useGlobalSearchParams } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';

export function useOpenHelp(): () => void {
  const search = useGlobalSearchParams();
  const target = String(search['url']);
  return () => {
    void WebBrowser.openBrowserAsync(target);
  };
}

// src/features/tasks/use-return-to.ts
// Sends the user back to the "returnTo" URL a link carries: any link can now open any site.
import { useLocalSearchParams } from 'expo-router';
import { Linking } from 'react-native';

export function useReturnTo(): () => void {
  const { returnTo } = useLocalSearchParams<{ returnTo: string }>();
  return () => {
    void Linking.openURL(returnTo);
  };
}

// src/features/tasks/use-continue.ts
// Reads the raw params, narrows `next` to a string, then opens it in the browser: still the link's URL.
import { useLocalSearchParams } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';

export function useContinue(): () => void {
  const raw = useLocalSearchParams();
  const target =
    typeof raw['next'] === 'string' ? raw['next'] : '';
  return () => {
    void WebBrowser.openBrowserAsync(target);
  };
}

// src/features/help/use-help-return.ts
// Parses the route's params with its valibot parser, then opens the parsed returnTo: a v.url() field
// still passes any URL, so the link opens any site with the app's trust.
import { useLocalSearchParams } from 'expo-router';
import { Linking } from 'react-native';

import { parseHelpParams } from './help-params';

export function useHelpReturn(): () => void {
  const parsed = parseHelpParams(useLocalSearchParams());
  return () => {
    if (parsed.ok) void Linking.openURL(parsed.value.returnTo);
  };
}

// src/app/(app)/settings/region.tsx
export default function Route(): null {
  return null;
}

// src/app/invite/region.tsx
export default function Route(): null {
  return null;
}

// src/features/auth/use-sign-in-start.ts
// The app's own OAuth start: the authorize URL is built from constants; the only link param read
// here is an error to show. A local `params` (URLSearchParams) is not a link's params.
import { useLocalSearchParams } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';

const AUTHORIZE_URL = 'https://auth.acme.dev/authorize';
const REDIRECT_URI = 'acme-tasks://oauth-redirect';

export function useSignInStart(): { readonly error: string | undefined; readonly start: () => void } {
  const { error } = useLocalSearchParams<{ error?: string }>();
  const start = (): void => {
    const params = new URLSearchParams({ client_id: 'tasks', redirect_uri: REDIRECT_URI, response_type: 'code' });
    void WebBrowser.openAuthSessionAsync(`${AUTHORIZE_URL}?${params.toString()}`, REDIRECT_URI);
  };
  return { error, start };
}

// src/features/tasks/use-open-task-web.ts
// Opens the task's web page: the link's param is parsed to an id, and the URL is built by a helper of
// src/config from the app's own origin, so the host never comes from the link.
import { useLocalSearchParams } from 'expo-router';
import { Linking } from 'react-native';

import { taskWebUrl } from '@/config/links';

import { parseTaskId } from './task-id';

export function useOpenTaskWeb(): () => void {
  const params = useLocalSearchParams();
  const id = parseTaskId(params['taskId']);
  return () => {
    void Linking.openURL(taskWebUrl(id));
  };
}

/** The same URL bound to a name first: still built by the config helper, still accepted. */
export function useOpenTaskWebBound(): () => void {
  const { taskId } = useLocalSearchParams();
  const webUrl = taskWebUrl(parseTaskId(taskId));
  return () => {
    void Linking.openURL(webUrl);
  };
}

// src/app/(app)/sessions/[sessionId].tsx
export default function Route(): null {
  return null;
}
